<template><section aria-label="随机密码生成"><p class="tool-note">使用 crypto.getRandomValues 生成随机密码，不使用 Math.random。每条包含所有已选字符类型，不上传、不写入浏览器存储，也不会自动复制。</p><div class="tool-actions"><label>密码长度<input v-model.number="length" type="number" min="4" max="128" aria-label="密码长度" /></label><label>生成数量<input v-model.number="count" type="number" min="1" max="20" aria-label="密码生成数量" /></label></div><div class="tool-actions"><label><input v-model="lower" type="checkbox" />小写字母</label><label><input v-model="upper" type="checkbox" />大写字母</label><label><input v-model="digits" type="checkbox" />数字</label><label><input v-model="symbols" type="checkbox" />符号</label><label><input v-model="excludeSimilar" type="checkbox" />排除易混淆字符 Il1O0o</label></div><div class="tool-actions"><button type="button" @click="generate">生成随机密码</button><button type="button" :disabled="!passwords.length" @click="copy">复制全部密码</button><button type="button" @click="passwords=[];message=''">清空生成的密码</button><label><input v-model="visible" type="checkbox" />显示密码</label></div><div v-for="(password,index) in passwords" :key="index" class="password-row"><input :type="visible?'text':'password'" :value="password" :aria-label="'生成的密码 '+(index+1)" readonly autocomplete="off" /><button type="button" @click="copyOne(password)">复制第 {{index+1}} 条</button></div><p role="status">{{message}}</p></section></template>
<script>
import {generatePasswords} from '../../utils/language-privacy-tools.mjs';
export default {name:'PasswordTool',data:()=>({length:20,count:1,lower:true,upper:true,digits:true,symbols:true,excludeSimilar:true,passwords:[],visible:false,message:''}),watch:{length(){this.invalidate();},count(){this.invalidate();},lower(){this.invalidate();},upper(){this.invalidate();},digits(){this.invalidate();},symbols(){this.invalidate();},excludeSimilar(){this.invalidate();}},beforeUnmount(){this.passwords=[];},methods:{invalidate(){this.passwords=[];this.message='设置已更改，请重新生成';},generate(){try{this.passwords=generatePasswords(this);this.message='已生成 '+this.passwords.length+' 条随机密码，请自行保管；刷新后清空';}catch(error){this.passwords=[];this.message=error.message;}},async copy(){await this.copyOne(this.passwords.join('\n'));},async copyOne(value){try{await navigator.clipboard.writeText(value);this.message='已复制密码';}catch{this.message='复制未完成，可显示并选择密码手动复制';}}}};
</script>
<style scoped>.password-row{display:flex;gap:8px;margin:8px 0;flex-wrap:wrap;}.password-row input{flex:1 1 200px;min-width:0;font-family:Consolas,monospace;}</style>
